    public static boolean supports(String cls){String c=key(cls);return c.equals("blood_hunter")||c.equals("necromancer")||c.equals("chronomancer")||c.equals("death_knight")||c.equals("shaman");}
    public static boolean fullCaster(String cls){String c=key(cls);return c.equals("necromancer")||c.equals("chronomancer")||c.equals("shaman");}
    public static boolean halfCaster(String cls){return key(cls).equals("death_knight");}
    public static JSONObject lookup(String cls){JSONObject o=new JSONObject();try{String c=key(cls);if(c.equals("blood_hunter"))return o.put("known",true).put("class","Caçador de Sangue").put("source",BLOOD).put("runtime","HomebrewClassRuntimeEngine");if(c.equals("necromancer"))return o.put("known",true).put("class","Necromante").put("source",NECRO).put("runtime","HomebrewClassRuntimeEngine");if(c.equals("chronomancer"))return o.put("known",true).put("class","Cronomancer").put("source",CHRONO).put("runtime","HomebrewClassRuntimeEngine");if(c.equals("death_knight"))return o.put("known",true).put("class","Cavaleiro da Morte").put("source",DEATH).put("runtime","HomebrewClassRuntimeEngine");if(c.equals("shaman"))return o.put("known",true).put("class","Xamã").put("source",SHAMAN).put("runtime","HomebrewClassRuntimeEngine");return o.put("known",false);}catch(Exception e){return o;}}


    /** Registra autoridade mecânica revisada para impedir estado apenas-catalogado. */
    public static JSONObject install(){JSONObject out=new JSONObject();JSONArray failed=new JSONArray();int ok=0;try{for(String cls:CLASSES){JSONObject m=lookup(cls);String source=m.optString("source"),sha=source.equals(BLOOD)?BLOOD_SHA:source.equals(NECRO)?NECRO_SHA:source.equals(CHRONO)?CHRONO_SHA:source.equals(DEATH)?DEATH_SHA:SHAMAN_SHA;String eid="run137.class."+key(cls);JSONObject ev=new JSONObject().put("evidence_id",eid).put("content_kind","class").put("content_name",cls).put("source_book",source).put("source_locator","class rules and progression table").put("source_sha256",sha).put("revision",1);JSONObject er=AuthorizedMechanicalEvidenceRegistry.registerReviewed(ev);if(!er.optBoolean("registered",false)){failed.put(cls+":"+er.optString("authority"));continue;}JSONObject basis=new JSONObject().put("source_type","reviewed_evidence").put("evidence_id",eid).put("content_kind","class").put("content_name",cls).put("source_book",source).put("source_locator","class rules and progression table").put("source_sha256",sha).put("revision",1);JSONObject mech=new JSONObject().put("effect_pipeline_complete",true).put("execution_status","compiled_effect_pipeline").put("runtime_resolver","HomebrewClassRuntimeEngine.execute").put("structured_class_runtime",true).put("auto_rolls",false).put("auto_mutation_allowed",false);JSONObject rr=CompiledContentMechanicsEngine.register("class",cls,mech,basis);if(rr.optBoolean("registered",false))ok++;else failed.put(cls+":"+rr.optString("authority"));}return out.put("installed",ok).put("expected",CLASSES.length).put("failed",failed).put("complete",ok==CLASSES.length).put("auto_rolls",false);}catch(Exception e){try{return out.put("installed",ok).put("expected",CLASSES.length).put("failed",failed).put("complete",false).put("error",e.getClass().getSimpleName());}catch(Exception ignored){return out;}}}
